}

interface Profile {
    userId: string;
    displayname?: string;
    avatarUrl?: string;
}

export function usePermalink({ room, type, url }: Args): HookResult {
    const resourceId = url ? getPrimaryPermalinkEntity(url) : null;
    const effectiveType = type ?? (resourceId?.[0] === \"@\"
        ? PillType.UserMention
        : resourceId?.[0] === \""'!" || resourceId?.[0] === "#"
          ? PillType.RoomMention
          : null);
    const userId = effectiveType === PillType.UserMention && resourceId?.[0] === "@" ? resourceId : null;
    const localMember = userId ? room?.getMember(userId) : null;
    const [profile, setProfile] = useState<Profile | null>(null);

    useEffect(() => {
        if (!userId || localMember) return;
        let active = true;
        MatrixClientPeg.get()
            .getProfileInfo(userId)
            .then((resp) => {
                if (active) setProfile({ userId, displayname: resp.displayname, avatarUrl: resp.avatar_url });
            })
            .catch((err) => logger.error("Could not retrieve profile data for " + userId + ":", err));
        return () => { active = false; };
    }, [userId, localMember]);

    const member = useMemo(() => {
        if (!userId) return null;
        if (localMember) return localMember;
        const fallback = new RoomMember(null, userId);
        if (profile?.userId === userId) {
            fallback.name = profile.displayname;
            fallback.rawDisplayName = profile.displayname;
            fallback.events.member = {
                getContent: () => ({ avatar_url: profile.avatarUrl }),
                getDirectionalContent: function () { return this.getContent(); },
            } as MatrixEvent;
        }
        return fallback;
    }, [userId, localMember, profile]);

    if (effectiveType === PillType.AtRoomMention) {
        return {
            avatar: room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
            text: "@room",
            onClick: null,
            resourceId: room?.roomId ?? null,
            type: effectiveType,
        };
    }

    if (effectiveType === PillType.UserMention && member) {
        return {
            avatar: <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />,
            text: member.rawDisplayName || userId,
            onClick: (e: ButtonEvent) => {
                e.preventDefault();
                dis.dispatch({ action: Action.ViewUser, member });
            },
            resourceId: userId,
            type: effectiveType,
        };
    }

    if (effectiveType === PillType.RoomMention && resourceId && (resourceId[0] === "!" || resourceId[0] === "#")) {
        const client = MatrixClientPeg.get();
        const resolvedRoom = resourceId[0] === "#"
            ? client.getRooms().find((candidate) =>
                candidate.getCanonicalAlias() === resourceId || candidate.getAltAliases().includes(resourceId))
            : client.getRoom(resourceId);
        return {
            avatar: resolvedRoom ? <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" /> : null,
            text: resolvedRoom?.name || resourceId,
            onClick: null,
            resourceId,
            type: resolvedRoom?.isSpaceRoom() ? "space" : effectiveType,
        };
    }

    return { avatar: null, text: null, onClick: null, resourceId: null, type: null };
}
